function CountOpening(brackets: string): int
    reads brackets
    requires brackets != null
    ensures 0 <= CountOpening(brackets) <= |brackets|
{
    var count := 0;
    foreach b in brackets {
        if b == '(' {
            count := count + 1;
        }
    }
    return count;
}

function CountClosing(brackets: string): int
    reads brackets
    requires brackets != null
    ensures 0 <= CountClosing(brackets) <= |brackets|
{
    var count := 0;
    foreach b in brackets {
        if b == ')' {
            count := count + 1;
        }
    }
    return count;
}

function NoExcessClosing(brackets: string): bool
    reads brackets
    requires brackets != null
    ensures NoExcessClosing(brackets) <==> (forall i :: 0 <= i < |brackets| ==>
        (CountOpening(substr(brackets, 0, i)) >= CountClosing(substr(brackets, 0, i))))
{
    var balance := 0;
    foreach b in brackets {
        if b == '(' {
            balance := balance + 1;
        } else if b == ')' {
            balance := balance - 1;
        }
        if balance < 0 {
            return false;
        }
    }
    return true;
}
